// Builds supabase/maintenance/bootstrap_new_project.sql — every migration, in
// order, as ONE paste for a BRAND NEW Supabase project.
//
// PURE. Importing this writes nothing. The writer is bundle-migrations.mjs,
// split off deliberately: the drift test imports buildBundle() to compare
// against the committed file, and if importing also WROTE the file the test
// would regenerate its own subject and could never fail.
//
// Why a bundle rather than "paste the nine files in order": migration 0006
// went in half-applied once, because it was handed over split across a chat
// message and a follow-up. The column and CHECK landed, all three functions
// did not, and it looked exactly like a stale PostgREST schema cache. Nine
// separate pastes is nine chances to repeat that. One block is one chance.
//
// GENERATED — never hand-edit the output. Edit the migrations and re-run:
//   node scripts/bundle-migrations.mjs
// A test asserts the committed bundle matches the migrations, so it cannot
// silently drift into being a stale copy of the schema.

import { readFileSync, readdirSync } from 'node:fs'
import { fileURLToPath } from 'node:url'
import { dirname, join } from 'node:path'

const root = dirname(dirname(fileURLToPath(import.meta.url)))
const migrationsDir = join(root, 'supabase', 'migrations')
export const OUTPUT = join(root, 'supabase', 'maintenance', 'bootstrap_new_project.sql')

export function migrationFiles() {
  return readdirSync(migrationsDir)
    .filter((f) => f.endsWith('.sql'))
    .sort() // 0001..0009 — zero-padded, so lexical order IS numeric order
}

export function buildBundle() {
  const files = migrationFiles()
  const header = `-- Kira — bootstrap a NEW Supabase project.
--
-- GENERATED by scripts/bundle-migrations.mjs. Do not hand-edit: edit the
-- migrations in supabase/migrations/ and re-run it. A test fails if this file
-- and those migrations disagree.
--
-- WHAT THIS IS
--   All ${files.length} migrations concatenated in order, so a fresh project reaches the
--   current schema in ONE paste. It is for an EMPTY project only.
--
-- DO NOT RUN THIS AGAINST PRODUCTION (${'ccbioktxfpeqaocjkqpr'}).
--   Production already has 0001-000${files.length} applied. Re-running would not be a
--   harmless no-op: 0001 creates tables, and \`create table\` without
--   \`if not exists\` errors rather than skipping. Some statements would abort
--   and others would not, which is the half-applied state that is genuinely
--   hard to reason about afterwards.
--
-- WHY ONE BLOCK
--   0006 was once handed over split across two messages and only the first
--   half ran — column and CHECK created, three functions missing. It looked
--   exactly like a stale PostgREST schema cache. Diagnose that class of
--   problem with \`select proname from pg_proc where pronamespace =
--   'public'::regnamespace\` BEFORE reaching for a schema reload.
--
-- AFTER PASTING
--   Check the function list is complete, then point a client at the new
--   project and confirm RLS actually denies a cross-user read. A table created
--   without \`enable row level security\` looks like a working feature from the
--   client and is a wide-open door.
--
-- Files, in application order:
${files.map((f) => `--   ${f}`).join('\n')}

`

  const body = files
    .map((f) => {
      const sql = readFileSync(join(migrationsDir, f), 'utf8').replace(/\s+$/, '')
      return `-- ===========================================================================
-- ${f}
-- ===========================================================================

${sql}
`
    })
    .join('\n')

  return header + body
}

